#pragma once

#include <driver/gpio.h>
#include <driver/ledc.h>

// One input pin of a DRV8871, generated by an LEDC channel.
class DriverInput
{
    public:
        // Where the input is wired: the GPIO and the LEDC channel that drives it.
        struct Wiring
        {
            public:
                gpio_num_t pin;
                ledc_channel_t channel;
        };

        explicit DriverInput(const Wiring &wiring) : wiring_(wiring) {}

        // Routes the channel to the pin, starting low: the driver reads 0, as during the reset
        // (ADR 008). Called once, at boot, after the timer is configured.
        void start(ledc_timer_t timer);

        void hold_high();

        // Low during `fraction` of each PWM period and high for the rest.
        void pulse_low(float fraction);

    private:
        void set_high_fraction(float fraction);

        Wiring wiring_;
};
